"use client";

import type { ReactNode } from "react";

export type ToastVariant = "neutral" | "info" | "success" | "warning" | "error";

export interface ToastOptions {
  description?: string;
  variant?: ToastVariant;
  duration?: number;
  action?: ReactNode;
}

interface Notification extends ToastOptions {
  id: number;
  message: string;
}

const empty: readonly Notification[] = [];
let notifications = empty;
let nextId = 0;
const listeners = new Set<() => void>();

function publish(next: readonly Notification[]) {
  notifications = next;
  listeners.forEach((listener) => listener());
}

function show(message: string, options: ToastOptions = {}) {
  const id = ++nextId;
  publish([{ ...options, id, message }, ...notifications].slice(0, 3));
  return id;
}

export const toast = Object.assign(show, {
  neutral: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "neutral" }),
  info: (message: string, options?: ToastOptions) => show(message, { ...options, variant: "info" }),
  success: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "success" }),
  warning: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "warning" }),
  error: (message: string, options?: ToastOptions) =>
    show(message, { ...options, variant: "error" }),
  dismiss: (id?: number) =>
    publish(id === undefined ? empty : notifications.filter((item) => item.id !== id)),
});

export const toastStore = {
  subscribe(listener: () => void) {
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  },
  getSnapshot: () => notifications,
  getServerSnapshot: () => empty,
};

"use client";

import {
  memo,
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import * as motion from "motion/react-client";
import { AnimatePresence, useReducedMotion } from "motion/react";
import { CircleCheck, CircleX, Info, TriangleAlert, X } from "lucide-react";
import { Card } from "./card";
import { Button } from "./button";
import { toast, toastStore, type ToastVariant } from "./toast-store";

export { toast } from "./toast-store";
export type { ToastOptions, ToastVariant } from "./toast-store";

interface ToastProps {
  message?: string;
  description?: string;
  variant?: ToastVariant;
  duration?: number;
  paused?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  action?: ReactNode;
  className?: string;
}

const statuses = {
  neutral: { icon: Info, color: "text-muted-foreground" },
  info: { icon: Info, color: "text-sky-700 dark:text-sky-400" },
  success: { icon: CircleCheck, color: "text-emerald-700 dark:text-emerald-400" },
  warning: { icon: TriangleAlert, color: "text-amber-700 dark:text-amber-400" },
  error: { icon: CircleX, color: "text-red-700 dark:text-red-400" },
};

export const Toast = memo(function Toast({
  message = "Your changes have been saved.",
  description = "Everything is up to date.",
  variant = "success",
  duration = 5000,
  paused: pauseTimer = false,
  open,
  onOpenChange,
  action,
  className = "",
}: ToastProps = {}) {
  const [visible, setVisible] = useState(true);
  const [interacting, setInteracting] = useState(false);
  const paused = pauseTimer || interacting;
  const isOpen = open ?? visible;
  const remaining = useRef(duration);
  const reducedMotion = useReducedMotion();
  const { icon: Icon, color } = statuses[variant];
  const dismiss = useCallback(() => {
    setVisible(false);
    onOpenChange?.(false);
  }, [onOpenChange]);

  useEffect(() => {
    remaining.current = duration;
  }, [duration, isOpen, message]);
  useEffect(() => {
    if (!isOpen || paused || duration <= 0) return;
    const started = Date.now();
    const timer = window.setTimeout(dismiss, Math.max(0, remaining.current));
    return () => {
      window.clearTimeout(timer);
      remaining.current = Math.max(0, remaining.current - (Date.now() - started));
    };
  }, [isOpen, paused, duration, message, dismiss]);

  return (
    <AnimatePresence initial={false}>
      {isOpen && (
        <motion.div
          initial={reducedMotion ? false : { opacity: 0, y: 16, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: reducedMotion ? 0 : 12, scale: reducedMotion ? 1 : 0.98 }}
          transition={{ duration: reducedMotion ? 0 : 0.2, ease: "easeOut" }}
          onPointerEnter={() => setInteracting(true)}
          onPointerLeave={(event) => {
            if (!event.currentTarget.contains(document.activeElement)) setInteracting(false);
          }}
          onFocusCapture={() => setInteracting(true)}
          onBlurCapture={(event) => {
            if (
              !event.currentTarget.contains(event.relatedTarget) &&
              !event.currentTarget.matches(":hover")
            )
              setInteracting(false);
          }}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              event.stopPropagation();
              dismiss();
            }
          }}
          className={`w-full max-w-sm ${className}`}
        >
          <Card title="" description="" className="h-full w-full! max-w-none! p-4!">
            <div className="flex items-start gap-3">
              <Icon aria-hidden="true" className={`mt-0.5 size-5 shrink-0 ${color}`} />
              <div
                className="min-w-0 flex-1"
                role={variant === "error" ? "alert" : "status"}
                aria-atomic="true"
              >
                <p className="text-base font-medium leading-6 text-foreground">{message}</p>
                {description && <p className={`mt-1 typography-body`}>{description}</p>}
              </div>
              <Button
                variant="ghost"
                aria-label="Dismiss notification"
                onClick={dismiss}
                className="-mr-1 -mt-1 size-9 min-h-0! shrink-0 p-0!"
              >
                <X aria-hidden="true" className="size-4" />
              </Button>
            </div>
            {action && <div className="mt-3 pl-8">{action}</div>}
          </Card>
        </motion.div>
      )}
    </AnimatePresence>
  );
});

function subscribeVisibility(listener: () => void) {
  document.addEventListener("visibilitychange", listener);
  return () => document.removeEventListener("visibilitychange", listener);
}

const getDocumentHidden = () => document.hidden;
const getServerHidden = () => false;

export const Toaster = memo(function Toaster() {
  const notifications = useSyncExternalStore(
    toastStore.subscribe,
    toastStore.getSnapshot,
    toastStore.getServerSnapshot,
  );
  const documentHidden = useSyncExternalStore(
    subscribeVisibility,
    getDocumentHidden,
    getServerHidden,
  );
  const [expanded, setExpanded] = useState(false);
  const reducedMotion = useReducedMotion();

  // A new batch must not inherit the previous stack's interaction state.
  if (notifications.length === 0 && expanded) setExpanded(false);

  return (
    <aside
      aria-label="Notifications"
      className="pointer-events-none fixed inset-x-4 bottom-4 z-[100] mx-auto w-auto max-w-sm sm:left-auto sm:mx-0 sm:w-96"
    >
      <div
        onPointerEnter={() => setExpanded(true)}
        onPointerLeave={(event) => {
          if (!event.currentTarget.contains(document.activeElement)) setExpanded(false);
        }}
        onFocusCapture={() => setExpanded(true)}
        onBlurCapture={(event) => {
          if (
            !event.currentTarget.contains(event.relatedTarget) &&
            !event.currentTarget.matches(":hover")
          )
            setExpanded(false);
        }}
        className={`relative grid items-end gap-3 pt-8 ${notifications.length ? "pointer-events-auto" : ""}`}
      >
        <AnimatePresence initial={false} mode="popLayout">
          {notifications.map((notification, depth) => (
            <motion.div
              key={notification.id}
              layout={!reducedMotion}
              initial={reducedMotion ? false : { opacity: 0, y: 20 }}
              animate={{
                opacity: 1,
                y: expanded ? 0 : -depth * 14,
                scale: expanded ? 1 : 1 - depth * 0.05,
              }}
              exit={{
                opacity: 0,
                y: reducedMotion ? 0 : 8,
                transition: { duration: reducedMotion ? 0 : 0.2, ease: "easeOut" },
              }}
              transition={
                reducedMotion
                  ? { duration: 0 }
                  : { type: "spring", stiffness: 280, damping: 30, opacity: { duration: 0.2 } }
              }
              style={{ zIndex: 3 - depth, order: -depth, transformOrigin: "center bottom" }}
              className={`min-h-0 min-w-0 ${expanded ? "[grid-area:auto]" : `[grid-area:1/1] ${depth ? "h-full overflow-hidden [contain:size]" : ""}`}`}
            >
              <Toast
                {...notification}
                open
                variant={notification.variant ?? "neutral"}
                description={notification.description ?? ""}
                paused={expanded || documentHidden}
                className="h-full"
                onOpenChange={(open) => {
                  if (!open) toast.dismiss(notification.id);
                }}
              />
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </aside>
  );
});

import { memo, type ComponentProps, type ReactNode } from "react";
import { cn } from "cn";

// Legacy content props remain supported for existing consumers.
const cardSizes = {
  sm: "gap-4 px-4 py-4",
  md: "gap-6 px-6 py-6",
} as const;

type CardProps = {
  size?: keyof typeof cardSizes;
  title?: string;
  description?: string;
  footer?: ReactNode;
} & (
  | ({ as?: "article" } & Omit<ComponentProps<"article">, "title">)
  | ({ as: "a" } & Omit<ComponentProps<"a">, "title">)
);

const Card = memo(function Card({
  title,
  description,
  children,
  footer,
  className,
  size = "md",
  ...props
}: CardProps) {
  const hasLegacyContent = Boolean(title || description || footer);
  const classes = cn(
    "group/card flex w-full max-w-sm flex-col rounded-lg surface-raised text-base leading-7",
    "outline-ring focus-visible:outline-[length:var(--focus-ring-width,2px)] focus-visible:outline-offset-[var(--focus-ring-offset,2px)]",
    "[a&]:transition-colors [a&]:duration-[var(--duration-fast,150ms)] [a&]:ease-out [a&]:hover:[--surface-bottom:var(--muted)] motion-reduce:transition-none",
    cardSizes[size],
    className,
  );
  const content = (
    <>
      {(title || description) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
      )}
      {hasLegacyContent ? children && <CardContent>{children}</CardContent> : children}
      {footer && <CardFooter>{footer}</CardFooter>}
    </>
  );
  if (props.as === "a") {
    const { as: Tag, ...anchorProps } = props;
    return (
      <Tag data-slot="card" data-size={size} className={classes} {...anchorProps}>
        {content}
      </Tag>
    );
  }
  const { as: Tag = "article", ...articleProps } = props;
  return (
    <Tag data-slot="card" data-size={size} className={classes} {...articleProps}>
      {content}
    </Tag>
  );
});

const CardHeader = memo(function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="card-header"
      className={cn(
        "grid auto-rows-min items-start gap-x-4 gap-y-2 has-[[data-slot=card-action]]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
});

const CardTitle = memo(function CardTitle({ className, ...props }: ComponentProps<"h3">) {
  return (
    <h3 data-slot="card-title" className={cn("typography-section-title", className)} {...props} />
  );
});

const CardDescription = memo(function CardDescription({
  className,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="card-description"
      className={cn("col-start-1", "typography-body", className)}
      {...props}
    />
  );
});

const CardAction = memo(function CardAction({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
});

const CardContent = memo(function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />;
});

const CardFooter = memo(function CardFooter({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      data-slot="card-footer"
      className={cn("flex items-center border-t border-border pt-4", className)}
      {...props}
    />
  );
});

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});
